#!/usr/bin/env node

import assert from "node:assert/strict";
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";

const GENERATED_BY = "tools/bpsr-harmony-grace-current-pack-boundary.mjs";
const SCHEMA_VERSION = 1;
const EFFECT_ID = 3_003_052;

// Historical schema-1 subset receipt verifier. New current-source closure
// receipts are generated by bpsr-harmony-grace-current-pack-lifecycle-closure.mjs
// after the legacy sticky unresolved-terminal suppression was disproven.

const [command = "help", ...rest] = process.argv.slice(2);
const options = parseArgs(rest);

if (command === "generate") {
  if (options["allow-superseded-historical-subset"] !== "true") {
    throw new Error(
      "schema-1 39-row boundary generation is superseded; use bpsr-harmony-grace-current-pack-lifecycle-closure.mjs, or pass --allow-superseded-historical-subset true only to reproduce the historical artifact",
    );
  }
  generate(options);
}
else if (command === "verify") verify(options);
else if (command === "self-test") selfTest();
else usage(command === "help" ? 0 : 1);

function generate(values) {
  const build = required(values, "build");
  const tracePath = path.resolve(required(values, "trace"));
  const auditPath = path.resolve(required(values, "audit"));
  const protocolStatusPath = path.resolve(required(values, "protocol-status"));
  const segmentReportPath = path.resolve(required(values, "segment-report"));
  const outputPath = path.resolve(required(values, "output"));
  refuseExisting(outputPath);

  const trace = readJson(tracePath);
  const audit = readJson(auditPath);
  const protocolStatus = readJson(protocolStatusPath);
  const segmentReport = readJson(segmentReportPath);
  const analysis = analyze({ build, trace, audit, protocolStatus, segmentReport });
  const report = {
    schema_version: SCHEMA_VERSION,
    generated_by: GENERATED_BY,
    game_build: build,
    effect_id: EFFECT_ID,
    identity: analysis.identity,
    inputs: {
      trace: fileReceipt(tracePath),
      replay_audit: fileReceipt(auditPath),
      protocol_status: fileReceipt(protocolStatusPath),
      run_segmentation: fileReceipt(segmentReportPath),
    },
    topology: {
      effect_edge: "provider -> effect/status lifecycle -> recipient or enemy target",
      damage_edge: "recipient damage action -> recipient or enemy target",
      target_allegiance_inferred: false,
      remote_player_cast_packet_required: false,
    },
    policy: {
      exact_numeric_ids_and_build_are_authoritative: true,
      localized_names_are_runtime_keys: false,
      unknown_or_unresolved_rows_synthesized: false,
      current_character_snapshots_used: false,
      ordinary_damage_totals_may_change: false,
      individually_valid_rows_suppressed_by_unproven_combined_mechanics_are_retained: true,
      provider_rdps_credit_allowed: false,
      runtime_promotion_allowed: false,
      ui_display_allowed: false,
    },
    proof: analysis.proof,
    summary: analysis.summary,
    blockers: [
      `${analysis.summary.combined_mechanic_suppressed_damage_rows} individually valid Harmony Grace rows remain suppressed because combined-mechanic operation order/allocation is not proven`,
      "a controlled absent/present/absent damage pair must validate the final server integer counterfactual instead of treating the exact rational transfer as a server-observed integer",
      "repeat the exact current-pack trace for additional recipient classes and provider combinations",
      "promote only a runtime rule whose exact non-overlap and stacking exclusions reproduce this boundary",
    ],
    decision: "exact-current-pack-closed-run-single-effect-slice-proven-runtime-disabled",
  };
  report.content_sha256 = contentHash(report);
  validateReport(report);
  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  fs.writeFileSync(outputPath, `${JSON.stringify(report, null, 2)}\n`, { flag: "wx" });
  process.stdout.write(`${JSON.stringify(report.summary, null, 2)}\n`);
}

function analyze({ build, trace, audit, protocolStatus, segmentReport }) {
  assert.match(build, /^\d+$/);
  assert.equal(trace.schema_version, 6);
  assert.equal(trace.generated_by, "tools/bpsr-harmony-grace-single-effect-trace.mjs");
  assert.equal(String(trace.game_build), build);
  assert.equal(Number(trace.effect_id), EFFECT_ID);
  assert.equal(trace.proof.formula_trace_proven_for_observed_rows, true);
  assert.equal(trace.proof.exact_provider_recipient_lifecycle, true);
  assert.equal(trace.proof.replay_conserved, true);
  assert.equal(trace.policy.provider_rdps_credit_allowed, false);
  assert.ok(Array.isArray(trace.traces) && trace.traces.length > 0);

  assert.equal(audit.schema_version, 23);
  assert.equal(audit.attribution_mode, "offline_candidate_gate_audit_not_production_attribution");
  assert.equal(audit.harmony_grace_candidate_audit_enabled, true);
  assert.ok(Array.isArray(audit.reports) && audit.reports.length === 1);
  const replay = audit.reports[0];
  assert.equal(String(replay.client_build), build);
  assert.equal(replay.session_id, trace.session_id);
  assert.equal(replay.protocol_pack_digest, trace.protocol_pack_digest);
  assert.equal(replay.candidate_audit_target_match, true);
  assert.equal(replay.conserved, true);
  assert.equal(Number(replay.emitted_contribution_events_by_effect?.[EFFECT_ID]), trace.traces.length);
  assert.equal(replay.emitted_contribution_ledger.length, trace.traces.length);

  const ledgerBySequence = new Map(
    replay.emitted_contribution_ledger.map((row) => [Number(row.sequence), row]),
  );
  for (const row of trace.traces) {
    const ledger = ledgerBySequence.get(Number(row.damage_sequence));
    assert.ok(ledger, `trace sequence ${row.damage_sequence} is absent from replay ledger`);
    assert.equal(Number(ledger.effect_id), EFFECT_ID);
    assert.equal(String(ledger.provider_actor_id), String(row.provider_actor_id));
    assert.equal(String(ledger.recipient_actor_id), String(row.recipient_actor_id));
    assert.equal(String(ledger.target_actor_id), String(row.damage_target_actor_id));
    assert.equal(String(ledger.numerator), String(row.contribution.numerator));
    assert.equal(String(ledger.denominator), String(row.contribution.denominator));
  }

  assert.equal(protocolStatus.schema_version, 4);
  assert.equal(protocolStatus.generated_by, "tools/bpsr-protocol-pack-status.mjs");
  assert.equal(String(protocolStatus.game_build), build);
  assert.equal(protocolStatus.status, "promoted");
  assert.equal(protocolStatus.candidate.audited_digest, trace.protocol_pack_digest);
  assert.equal(protocolStatus.promoted_pack.present, true);
  assert.equal(protocolStatus.promoted_pack.build_matches, true);
  assert.equal(protocolStatus.promoted_pack.byte_identical_to_candidate, true);
  assert.equal(
    protocolStatus.policy.structurally_unobservable_remote_player_packets_are_not_acquisition_requirements,
    true,
  );
  assert.equal(protocolStatus.policy.unknown_and_unresolved_canonical_events_are_preserved, true);

  assert.equal(segmentReport.schema_version, 1);
  assert.equal(String(segmentReport.requirements.expected_build), build);
  assert.equal(
    segmentReport.requirements.expected_protocol_pack_digest,
    trace.protocol_pack_digest,
  );
  assert.equal(segmentReport.requirements.remote_player_cast_packet_required, false);
  assert.equal(String(segmentReport.source.header.region.client_build), build);
  assert.equal(
    segmentReport.source.header.region.protocol_pack_digest,
    trace.protocol_pack_digest,
  );
  const segment = segmentReport.segments.find((row) => row.session_id === trace.session_id);
  assert.ok(segment, `segmentation has no ${trace.session_id}`);
  assert.equal(segment.completed, true);

  const exact = sumFractions(trace.traces.map((row) => row.contribution));
  assert.equal(trace.summary.exact_contribution.numerator, exact.numerator.toString());
  assert.equal(trace.summary.exact_contribution.denominator, exact.denominator.toString());
  const integerProjection = roundHalfUp(exact.numerator, exact.denominator);
  const effect = replay.summary.effects.find(
    (row) => Number(row.effect_id) === EFFECT_ID
      && String(row.provider_actor_id) === String(trace.traces[0].provider_actor_id)
      && String(row.recipient_actor_id) === String(trace.traces[0].recipient_actor_id),
  );
  assert.ok(effect, "replay summary omits the exact Harmony Grace transfer");
  assert.equal(BigInt(effect.amount), integerProjection);
  assert.equal(BigInt(replay.summary.attributed_bonus_damage), integerProjection);
  assert.equal(Number(replay.summary.attributed_damage_event_count), trace.traces.length);

  const rawTotal = actorTotal(replay.summary.actors, "raw_damage");
  const rdpsTotal = actorTotal(replay.summary.actors, "rdps_damage");
  assert.equal(rawTotal, rdpsTotal);
  const individuallyValid = Number(replay.harmony_grace_audit_gates?.emitted ?? 0);
  assert.ok(individuallyValid >= trace.traces.length);

  return {
    identity: {
      deployment_id: replay.deployment_id,
      session_id: trace.session_id,
      protocol_pack_digest: trace.protocol_pack_digest,
      provider_actor_id: String(trace.traces[0].provider_actor_id),
      recipient_actor_id: String(trace.traces[0].recipient_actor_id),
      lifecycle_instance_ids: [...new Set(trace.traces.map((row) => row.lifecycle.instance_id))],
    },
    proof: {
      exact_current_pack_identity: true,
      protocol_event_coverage_promoted: true,
      packet_batched_closed_run: true,
      exact_provider_recipient_lifecycle: true,
      exact_formula_trace_for_emitted_rows: true,
      exact_rational_transfer_replayed: true,
      integer_projection_matches_replay_summary: true,
      ordinary_damage_conserved: true,
      unproven_combined_mechanic_rows_received_zero_credit: true,
    },
    summary: {
      closed_run_events: Number(segment.event_count),
      individually_valid_harmony_damage_rows: individuallyValid,
      exact_nonoverlap_emitted_damage_rows: trace.traces.length,
      combined_mechanic_suppressed_damage_rows: individuallyValid - trace.traces.length,
      observed_damage: String(trace.summary.observed_damage),
      exact_contribution: trace.summary.exact_contribution,
      integer_projected_contribution: integerProjection.toString(),
      ordinary_raw_damage: rawTotal.toString(),
      ordinary_rdps_damage: rdpsTotal.toString(),
    },
  };
}

function verify(values) {
  const inputPath = path.resolve(required(values, "input"));
  const report = readJson(inputPath);
  validateReport(report);
  for (const descriptor of Object.values(report.inputs)) verifyReceipt(descriptor);
  const analysis = analyze({
    build: report.game_build,
    trace: readJson(report.inputs.trace.path),
    audit: readJson(report.inputs.replay_audit.path),
    protocolStatus: readJson(report.inputs.protocol_status.path),
    segmentReport: readJson(report.inputs.run_segmentation.path),
  });
  assert.deepEqual(report.identity, analysis.identity);
  assert.deepEqual(report.proof, analysis.proof);
  assert.deepEqual(report.summary, analysis.summary);
  process.stdout.write(`${JSON.stringify(report.summary, null, 2)}\n`);
}

function validateReport(report) {
  assert.equal(report.schema_version, SCHEMA_VERSION);
  assert.equal(report.generated_by, GENERATED_BY);
  assert.equal(Number(report.effect_id), EFFECT_ID);
  assert.equal(report.topology.target_allegiance_inferred, false);
  assert.equal(report.topology.remote_player_cast_packet_required, false);
  assert.equal(report.policy.provider_rdps_credit_allowed, false);
  assert.equal(report.policy.runtime_promotion_allowed, false);
  assert.equal(report.policy.ui_display_allowed, false);
  assert.equal(report.proof.ordinary_damage_conserved, true);
  assert.equal(report.decision, "exact-current-pack-closed-run-single-effect-slice-proven-runtime-disabled");
  assert.equal(report.content_sha256, contentHash(report));
}

function selfTest() {
  assert.deepEqual(sumFractions([{ numerator: "1", denominator: "3" }, { numerator: "1", denominator: "6" }]), { numerator: 1n, denominator: 2n });
  assert.equal(roundHalfUp(7n, 2n), 4n);
  assert.equal(roundHalfUp(6n, 2n), 3n);
  process.stdout.write("self-test passed\n");
}

function sumFractions(rows) {
  let numerator = 0n;
  let denominator = 1n;
  for (const row of rows) {
    numerator = numerator * BigInt(row.denominator) + BigInt(row.numerator) * denominator;
    denominator *= BigInt(row.denominator);
    const divisor = gcd(numerator, denominator);
    numerator /= divisor;
    denominator /= divisor;
  }
  return { numerator, denominator };
}

function roundHalfUp(numerator, denominator) {
  assert.ok(numerator >= 0n && denominator > 0n);
  return (numerator * 2n + denominator) / (denominator * 2n);
}

function gcd(left, right) {
  left = left < 0n ? -left : left;
  right = right < 0n ? -right : right;
  while (right !== 0n) [left, right] = [right, left % right];
  return left;
}

function actorTotal(actors, field) {
  return Object.values(actors).reduce((sum, actor) => sum + BigInt(actor[field]), 0n);
}

function fileReceipt(filePath) {
  const bytes = fs.readFileSync(filePath);
  return { path: filePath, bytes: bytes.length, sha256: sha256(bytes) };
}

function verifyReceipt(descriptor) {
  const current = fileReceipt(descriptor.path);
  assert.equal(current.bytes, descriptor.bytes);
  assert.equal(current.sha256, descriptor.sha256);
}

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, "utf8"));
}

function sha256(value) {
  return crypto.createHash("sha256").update(value).digest("hex");
}

function contentHash(report) {
  const copy = structuredClone(report);
  delete copy.content_sha256;
  return sha256(Buffer.from(JSON.stringify(copy)));
}

function refuseExisting(filePath) {
  if (fs.existsSync(filePath) || fs.existsSync(`${filePath}.partial`)) {
    throw new Error(`refusing to overwrite ${filePath}`);
  }
}

function required(values, key) {
  if (!values[key]) throw new Error(`missing --${key}`);
  return values[key];
}

function parseArgs(values) {
  const parsed = {};
  for (let index = 0; index < values.length; index += 2) {
    const key = values[index];
    if (!key?.startsWith("--") || index + 1 >= values.length) usage(1);
    parsed[key.slice(2)] = values[index + 1];
  }
  return parsed;
}

function usage(exitCode) {
  process.stderr.write(
    "usage:\n" +
      "  node tools/bpsr-harmony-grace-current-pack-boundary.mjs generate --allow-superseded-historical-subset true --build <id> --trace <json> --audit <json> --protocol-status <json> --segment-report <json> --output <json>\n" +
      "  node tools/bpsr-harmony-grace-current-pack-boundary.mjs verify --input <json>\n" +
      "  node tools/bpsr-harmony-grace-current-pack-boundary.mjs self-test\n",
  );
  process.exit(exitCode);
}
